function wingSpine(curve){
  const k = curve - 1;                                  // 1차 .20 · 2차 .12 — 1차가 조금 더 둥글게 솟는다
  const P1x = .24, P1y = .50 + .30*k, P2x = .98, P2y = 1.10 + .25*k, P3x = 1.64, P3y = .76;
  return (t)=>{ const u = 1-t, b = 3*u*u*t, c = 3*u*t*t, d = t*t*t;
    return [b*P1x + c*P2x + d*P3x, b*P1y + c*P2y + d*P3y]; };
}

function wingGeo(o){
  const C=wingSpine(o.curve),pos=[],colors=[],bone=[],piv=[],ids=[];
  const TE=.34,TW=.62,PE=C(TE),PW=C(TW);              // 팔꿈치·손목 — 앞전의 몇 % 자리인가
  const tn=t=>{const a=C(Math.max(0,t-.002)),b=C(Math.min(1,t+.002)),l=Math.hypot(b[0]-a[0],b[1]-a[1]);
    return [(b[0]-a[0])/l,(b[1]-a[1])/l,-(b[1]-a[1])/l,(b[0]-a[0])/l];};
  const sm=(a,b,x)=>{const u=Math.max(0,Math.min(1,(x-a)/(b-a)));return u*u*(3-2*u);};
  const wE=t=>sm(TE-.08,TE+.08,t),wW=t=>sm(TW-.07,TW+.07,t);
  const width=t=>.05*(1-t)+.25*Math.pow(Math.sin(Math.PI*t),.72);
  const V=(x,y,z,shade,be,bw,fk)=>{const i=pos.length/3;pos.push(x,y,z);colors.push(shade,shade,shade);
    bone.push(be,bw,fk,0);piv.push(PE[0],PE[1],PW[0],PW[1]);return i;};
  const Q=(a,b,c,d,back=false)=>{if(back)ids.push(a,c,b,a,d,c);else ids.push(a,b,c,a,c,d);};
  // 어깨부터 끝까지 이어진 얇은 곡면(덮깃 바탕)이 윤곽을 맡는다.
  for(const side of [-1,1]){
    const rows=[];
    for(let i=0;i<=24;i++){
      const t=i/24,c=C(t),n=tn(t),w=width(t),row=[];
      for(const v of [-1,-.5,0,.5,1]){
        const z=side*(.008+.020*(1-v*v)*Math.sin(Math.PI*t));
        row.push(V(c[0]+n[2]*w*v,c[1]+n[3]*w*v,z,.93+.05*(1-Math.abs(v)),wE(t),wW(t),0));
      }
      rows.push(row);
    }
    for(let i=0;i<24;i++)for(let k=0;k<4;k++)Q(rows[i][k],rows[i+1][k],rows[i+1][k+1],rows[i][k+1],side<0);
  }
  /* 깃 한 장 — 뿌리(rx,ry)에서 (dx,dy) 쪽으로 len. 깃대(가운데)가 살짝 솟고, 바깥 깃판이 안쪽보다 좁다(실제 깃처럼 비대칭).
     narrow 는 끝으로 갈수록 가늘어지는 정도(칼깃 끝의 홈). 끝은 둥글게 닫힌다. */
  let tipI=0,midI=0;
  const feather=(rx,ry,dx,dy,len,fw,z,s0,s1,be,bw,fk,side,narrow)=>{
    const rows=[];let tip=0;
    for(let j=0;j<=5;j++){
      const u=j/5,hw=fw*Math.sqrt(Math.max(0,Math.sin(Math.PI*(.06+.90*u))))*(1-narrow*u*u),x=rx+dx*len*u,y=ry+dy*len*u,sh=s0+(s1-s0)*u;
      rows.push([V(x-dy*hw*.80,y+dx*hw*.80,z,sh,be,bw,fk),tip=V(x,y,z+side*.007*Math.sin(Math.PI*u),sh+.03,be,bw,fk),
        V(x+dy*hw*1.12,y-dx*hw*1.12,z,sh-.06,be,bw,fk)]);
    }
    for(let j=0;j<5;j++){Q(rows[j][0],rows[j+1][0],rows[j+1][1],rows[j][1],side<0);
      Q(rows[j][1],rows[j+1][1],rows[j+1][2],rows[j][2],side<0);}
    return tip;
  };
  const dirTo=(ax,ay)=>{const l=Math.hypot(ax,ay);return [ax/l,ay/l];};
  const dW=tn(TW),down=Math.atan2(-dW[3],-dW[2])-.10,tE=tn(1),outA=Math.atan2(tE[1],tE[0])-.42;
  for(const side of [-1,1]){
    // 둘째날개깃 — 팔(어깨~손목) 아래로 가지런히, 바깥 것이 조금 길다
    for(let i=0;i<o.nS;i++){
      const f=i/(o.nS-1),t=.08+f*(TW-.10),c=C(t),n=tn(t),w=width(t),[dx,dy]=dirTo(-n[2]+n[0]*.20,-n[3]+n[1]*.20);
      const tip=feather(c[0]-n[2]*w*.25,c[1]-n[3]*w*.25,dx,dy,w*1.30+.10+.06*f,.088,side*(.016+.002*i),.94,.78+.04*(i%2),wE(t),wW(t),0,side,.05);
      if(side>0&&i===o.nS-2)midI=tip;
    }
    // 칼깃 — 손목에서 부챗살로. 안쪽은 아래(뒤)로, 바깥쪽은 날개 끝 방향으로 돌고 길어진다. 바깥 깃이 위로 겹친다.
    for(let i=0;i<o.nP;i++){
      const f=i/(o.nP-1),t=TW-.02+f*(.975-TW+.02),c=C(t),n=tn(t),w=width(t),a=down+(outA-down)*Math.pow(f,.85);
      const tip=feather(c[0]-n[2]*w*.20,c[1]-n[3]*w*.20,Math.cos(a),Math.sin(a),o.pl*(.64+.36*Math.pow(f,.8)),.094*(1-.14*f),
        side*(.021+.0034*i),.93,.64+.06*(i%2),1,1,f*2-1,side,.30*f);
      if(side>0&&i===o.nP-1)tipI=tip;
    }
    // 덮깃 — 앞전 바로 아래를 짧게 덮어 곡면과 깃의 경계를 감춘다
    for(let i=0;i<o.nC;i++){
      const f=i/Math.max(1,o.nC-1),t=.13+f*.58,c=C(t),n=tn(t),w=width(t),[dx,dy]=dirTo(-n[2]+n[0]*.22,-n[3]+n[1]*.22);
      feather(c[0]+n[2]*w*.62,c[1]+n[3]*w*.62,dx,dy,w*.78,.072*(1-.2*f),side*.044,.98,.93,wE(t),wW(t),0,side,0);
    }
  }
  const g=new THREE.BufferGeometry();
  g.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));
  g.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));
  g.setAttribute('wbone',new THREE.Float32BufferAttribute(bone,4));
  g.setAttribute('wpiv',new THREE.Float32BufferAttribute(piv,4));
  g.setIndex(ids);g.computeVertexNormals();g.computeBoundingBox();
  g.userData.tipI=tipI;g.userData.midI=midI;return g;
}

