const WMAT_W = (()=>{ const m = flatMat(0xffffff, {side:THREE.DoubleSide, vertexColors:true});
  const GLSL = 'attribute vec4 wbone; attribute vec4 wpiv; attribute vec4 wflex;\n'
    + 'vec2 wingRot(vec2 p, vec2 c, float a){ float s = sin(a), k = cos(a); p -= c; return c + vec2(p.x*k - p.y*s, p.x*s + p.y*k); }\n'
    + 'vec3 wingBend(vec3 p, float pt){ vec2 pe = wpiv.xy*pt, pw = wpiv.zw*pt;\n'
    + '  p.xy = wingRot(p.xy, pw, wflex.w*wbone.z + wflex.y*wbone.y);\n'
    + '  float a = wflex.z*wbone.y, s = sin(a), k = cos(a), dx = p.x - pw.x;\n'
    + '  p.x = pw.x + dx*k + p.z*s; p.z = p.z*k - dx*s;\n'
    + '  p.xy = wingRot(p.xy, pe, wflex.x*wbone.x); return p; }\n';
  m.userData.wingGLSL = GLSL;
  m.onBeforeCompile = (sh)=>{ sh.vertexShader = sh.vertexShader
      .replace('#include <common>', '#include <common>\n' + GLSL)
      .replace('#include <beginnormal_vertex>', '#include <beginnormal_vertex>\nobjectNormal = wingBend(objectNormal, 0.0);')
      .replace('#include <begin_vertex>', '#include <begin_vertex>\ntransformed = wingBend(transformed, 1.0);'); };
  m.customProgramCacheKey = ()=> 'wing-bend-66';
  return m; })();

