    const low=p.length/3;p.push(0,-.5,0);const top=p.length/3;p.push(0,kind==='safari'?.5:kind==='sheriff'?.07:.14,0);
    for(let i=0;i<N;i++){const a=(rows.length-1)*N+i,b=(rows.length-1)*N+(i+1)%N;ix.push(low,(i+1)%N,i,top,a,b);}
