    const armSwing=[0,0];   // 어깨 스윙을 팔꿈치 식이 다시 읽는다. 사람마다 새로 만든다.
    const armDiag=[0,0];    // 63차 — 대각선 몫만 따로 들고 있다가 아래팔에만 크게 준다
    const hipY = Y(R6_HIP);
    const gunPit=lean-kick*.15+(W3 ? W3.pit - 1.1*W3.draw : 0), gunC=Math.cos(gunPit),gunS=Math.sin(gunPit);
    const gunRoll=W3 ? W3.rol : 0, gunCR=Math.cos(gunRoll), gunSR=Math.sin(gunRoll);
    /* 70차 — 총 자리는 **조준 틀**의 몸 오른쪽(오른 가슴 앞 · 개머리가 오른 어깨에 닿는다). 새총·활은 왼손 자리(쭉 뻗어 든다) */
    const HL = TG0 && TG0.hand === 'L', gunF=(HL ? (s.wp === 8 ? .40 : .38) : GUN3P[0])+.05*glideK-kick*.012-(W3 ? W3.pull : 0), gunU=(HL ? 1.0 : GUN3P[1])+kick*.025-.12*glideK-.05*Math.min(1, land/.22), gunSd=HL ? .05 : GUN3P[2];   // 활공 땐 머리를 젖히므로 총을 조금 내린다
